from common import n, q
ROWS = [
n("traditional_fermentation",1,"传统发酵中的微生物与代谢",
  "传统发酵利用微生物代谢改变食物或形成产物，不同过程的微生物、底物和供氧需求不同。酵母酒精发酵、乳酸发酵和醋酸形成不能视为同一种反应；发酵生产的宽泛用语也不等于所有参与过程都在无氧条件下进行。",
  "对应常见发酵类型与主要代谢变化|区分酒精发酵与醋酸形成的供氧需求",
  q("比较典型酒精发酵与乳酸发酵，哪项产物对应正确？","前者可产生乙醇和二氧化碳，后者主要产生乳酸|前者主要产生乳酸，后者主要产生乙醇|两者都把葡萄糖彻底氧化成二氧化碳和水|两者必须产生相同数量的二氧化碳","典型酒精发酵与乳酸发酵的终产物不同，后者通常不伴随该途径释放二氧化碳。"),
  q("果醋生产中某些醋酸菌可在有氧条件下将乙醇氧化形成醋酸。这说明哪项判断不应作普遍结论？","发酵生产中的所有代谢过程都不需要氧|不同微生物可具有不同代谢方式|供氧条件会影响某些发酵产物|乙醇可成为某些后续微生物过程的底物","果醋相关氧化过程需要氧，说明宽泛的发酵生产包括不同供氧需求，不能把发酵一词一律等同于无氧代谢。"),
  "anaerobic_respiration>传统发酵需理解不彻底分解及其产物;~bacteria>乳酸菌与醋酸菌属于细菌背景;~fungi>酵母是真菌而非细菌"),
n("culture_and_asepsis",1,"培养条件、消毒灭菌与对照",
  "微生物生长需适宜营养和环境，培养基配方可通过营养等条件对不同微生物产生选择作用。消毒着重消除或降低病原微生物，灭菌要求消除包括芽孢在内的可存活微生物；无菌操作旨在避免外来污染。未接种培养基对照有助于判断污染。",
  "区分营养需要与无菌控制的作用|用空白对照评价污染及结论有效性|说明调整培养基配方可改变微生物的生长适宜性",
  q("比较消毒与灭菌的课程含义，哪项表述较准确？","灭菌要求消除可存活微生物，包括芽孢等形式|只要微生物暂时停止繁殖，就能认定已经灭菌|消毒只要使肉眼看不到菌落，就已达到灭菌要求|消毒与灭菌都以保留所有细菌芽孢为必要条件","灭菌针对可存活微生物及其芽孢等形式；暂时不繁殖或肉眼看不见菌落都不等于不存在可存活微生物。消毒与灭菌的要求不能混同。"),
  q("某教学微生物培养观察中，未接种的空白培养基也出现菌落，最合理的判断是？","存在污染等非目标来源的可能，需检查对照和过程|空白组菌落少于样品组，就足以保证样品结果可靠|从每个样品结果中扣除空白菌落数，就能排除所有污染影响|只要样品组菌落外观一致，就可忽略空白异常","未接种空白出现菌落提示污染或其他控制失效。菌落数量较少、外观相似或简单相减，都不足以自动排除污染对归因和估计的影响。"),
  "~bacteria>微生物生长需结合细胞代谢认识;~inquiry>对照用于区分目标来源和污染"),
n("microbial_isolation_count",1,"菌落、纯培养与活菌估计",
  "平板划线和稀释涂布可使微生物在培养表面分散，帮助分离独立菌落。菌落计数以能形成菌落的单位CFU表示，需校正稀释倍数和体积；一个单位可包含细胞团。显微镜直接计数统计观察到的细胞，未经特殊区分时可能包含死细胞，与CFU口径不同。",
  "区分菌落形成单位与绝对单细胞数|根据稀释和体积换算CFU浓度|比较分离方法的基本目的和显微镜直接计数的口径",
  q("某教学用非致病微生物样品的10⁻⁵稀释液，取0.1 mL用于计数，得到38个菌落。忽略其他误差，原液浓度估计为？","3.8×10⁷ CFU/mL|3.8×10⁶ CFU/mL|3.8×10⁵ CFU/mL|38 CFU/mL","原液浓度＝38÷0.1÷10⁻⁵＝3.8×10⁷ CFU/mL；须同时校正稀释和计数体积。"),
  q("为什么平板上的一个菌落形成单位不一定严格等于原样品中的一个活细胞？","相连细胞可能共同成落，部分活细胞也可能不能在给定条件下成落|只要校正稀释倍数和体积，细胞团就不再影响计数结果|任何活细胞都能在任意培养条件下形成单独菌落|显微镜下看到一个完整细胞，就能证明其必形成一个菌落","CFU反映在给定条件下能形成菌落的单位。细胞团、存活状态和培养适宜性都会影响它与实际活细胞数的关系；体积校正不能消除这些差异。"),
  "culture_and_asepsis>分离计数需先排除污染并满足适宜培养条件;~inquiry>数量估计需要清楚的测量口径"),
n("fermentation_engineering",1,"发酵工程的控制与产物评价",
  "发酵工程将菌种、培养体系、过程监测和产物获得等环节协调起来。温度、酸碱度和供氧等需与目标微生物和产物适配；菌体生长快、底物消耗多与目标产物产量高不完全等价，应采用明确的产物和资源效率指标评价。",
  "说明过程控制应匹配微生物与目标产物|区分菌体增长底物消耗和产物形成",
  q("某需氧发酵体系持续监测溶解氧，主要目的是？","判断供氧是否与细胞代谢需求相匹配|证明所有发酵过程都必须完全无氧|用氧气浓度直接替代所有产物测量|只要溶氧越高，任何微生物产量都必定越大","供氧应适配具体代谢需求，溶氧是过程控制指标之一，不是产量的通用替代量。"),
  q("两组发酵实验中，乙组消耗更多糖却未产生更多目标产物，哪种解释在原理上可能成立？","更多底物被用于菌体生长或其他代谢途径|消耗的糖只能进入目标产物，不可能有其他去向|底物消耗增加足以证明所有培养条件已最适|消耗的糖越多，就已证明目标产物纯度越高","底物可流向菌体生长、能量代谢及副产物等途径，消耗更多糖并不保证目标产量、纯度或培养条件均改善。"),
  "traditional_fermentation>需认识不同微生物代谢与产物;culture_and_asepsis>过程控制需兼顾适宜条件与污染控制"),
n("plant_tissue_culture",2,"植物组织培养与细胞全能性",
  "植物组织培养利用细胞的发育潜能：典型过程中，已分化细胞经脱分化恢复分裂能力并形成愈伤组织，再经再分化形成具有特定结构功能的组织器官，部分体系可再生完整植株。全能性是否表现取决于条件和结果，不能由保有遗传信息就推定任意条件都能成株。",
  "用完整植株再生判断全能性表现的证据|解释脱分化再分化与基因选择性表达的关系",
  q("从一个已分化植物体细胞获得完整可正常发育的植株，主要体现该细胞在这些条件下？","表现出形成完整个体的发育潜能|只能增殖，不能分化|必须先丢失大部分基因才能形成器官|已经成为自然受精形成的新受精卵","再生完整植株是全能性表现的重要证据；原细胞来源不因此变成受精卵。"),
  q("同一来源植物细胞在培养中先形成未分化细胞团，再分化出根和芽。哪些变化通常最需要考虑？","不同阶段基因表达与调节状态改变|每形成一种器官都必须重新合成一套完全不同基因组|所有细胞必须永久表达完全相同的基因组合|分化只取决于细胞数量，与信号和培养条件无关","增殖与分化涉及基因表达和信号调节，不要求每种组织换成完全无关的基因组。"),
  "differentiation_potential>组织培养需区分细胞增殖与完整个体再生;expression_traits>分化依赖选择性表达;culture_and_asepsis>离体培养需适宜环境与污染控制"),
n("plant_somatic_hybrid",2,"植物体细胞杂交与原生质体融合",
  "植物体细胞杂交通过原生质体融合等方式使来自不同细胞的遗传物质进入同一细胞，再经适宜培养尝试再生。它与精卵受精和仅转入一个基因不同，可跨越部分有性杂交限制，但融合不保证一定得到稳定可育的完整植株。",
  "区分体细胞融合与有性杂交及单基因转移|在明确无丢失条件下计算融合细胞染色体数",
  q("与仅向受体转入一个目标基因相比，两个植物体细胞核融合的突出区别是？","可能组合来自两个体细胞的较完整染色体组|仅把一个预先指定基因复制到另一细胞|只交换细胞壁材料，不组合核遗传物质|只组合经过减数分裂形成的两套配子染色体","体细胞核融合可能使两个体细胞的较完整染色体组组合，和配子受精或单个目标基因转移的范围不同。是否能稳定再生成株仍需后续条件。"),
  q("两个植物体细胞在同类未复制阶段分别有20条和30条染色体，原生质体核融合后无染色体丢失或额外加倍。杂种细胞相应阶段共有多少条？","50条|25条|100条|10条","题设排除丢失和额外加倍，因此两套来源的染色体相加：20＋30＝50。"),
  "plant_tissue_culture>获得完整杂种植株还需再生能力;membrane_model>原生质体融合涉及生物膜;~chromosome_number_variation>可将融合后的染色体组合与倍性概念联系"),
n("animal_cell_culture",2,"动物细胞培养与生长限制",
  "动物细胞培养在体外维持细胞生存与增殖，原代与分开后继续培养的传代过程不同。许多正常细胞有贴附要求和密度相关的增殖限制，可传代不等于癌变、无限增殖或形成完整动物。干细胞具有自我更新和一定的分化潜能，相关培养可用于再生研究、疾病模型等。",
  "区分细胞培养传代与完整个体形成|说明正常细胞增殖存在条件和限度|用自我更新与分化潜能解释干细胞的研究应用价值",
  q("把已有培养体系中的部分动物细胞分开，转入新的培养体系继续培养，通常称为？","传代培养|原代培养|细胞融合|胚胎移植","已有培养中的细胞分开后继续培养属于传代；从动物组织初次建立培养为原代。细胞融合和胚胎移植涉及不同对象与操作目标。"),
  q("某动物细胞完成了一次传代，仅此能否证明它已癌变并可无限增殖？","不能，传代能力本身不足以证明癌变或无限增殖|能，有限传代与无限增殖在定义上完全相同|能，只要细胞能离体生存，就符合癌变判据|不能，但只要细胞外形正常就可永久排除癌变","一些正常细胞也能在适宜条件下有限传代。一次传代既不证明癌变，也不证明无限增殖；仅看形态同样不能代替更完整的性质评价。"),
  "~mitotic_cycle>细胞周期提供增殖背景，但原代传代不以完整分裂计数为前提;differentiation_potential>需区分细胞增殖与完整个体再生;culture_and_asepsis>体外维持需控制营养环境与污染"),
n("hybridoma_antibody",2,"细胞融合与单克隆抗体",
  "教材常用的单克隆抗体模型将具有相应抗体产生能力的B淋巴细胞与能持续增殖的骨髓瘤细胞融合，筛选兼具相关功能的杂交瘤细胞。融合产物并非都符合目标，克隆与功能筛选目的不同；单克隆强调同一细胞克隆来源及相应抗体特异性。",
  "解释融合细胞需要兼具增殖与抗体分泌能力|区分发生融合和获得目标抗体细胞的证据",
  q("理想的抗体生产杂交细胞需要同时具备哪两项关键功能？","持续增殖潜能与分泌所需特异性抗体|持续增殖且无需具有所需抗体特异性|分泌所需抗体但不能再进行增殖|分泌任意多种抗体即可，无需单克隆来源","技术利用不同来源细胞的功能互补，既需增殖能力，也需所需抗体的分泌能力与相应单克隆特性。"),
  q("完成细胞融合后，为什么仍需检验所得细胞是否分泌目标抗体？","融合产物存在多种类型，融合本身不保证所需特异性和功能|任意两个细胞接触后都会只产生同一种目标抗体|所有B细胞本来就分泌完全相同的抗体，无需区分|只要检验出持续增殖能力，就已确定所分泌抗体的特异性","融合、增殖和目标抗体分泌是不同条件，需要相应筛选与功能证据，不能从融合一步直接推出全部成功。"),
  "humoral_immunity>需理解B细胞与抗体特异性;animal_cell_culture>杂交细胞增殖依赖细胞培养;~membrane_model>细胞融合与膜的性质有关"),
n("embryo_engineering",2,"体外受精、胚胎移植与分割",
  "胚胎工程包括与早期胚胎形成、培养、移植或分割有关的技术原理。胚胎移植改变发育所在母体，不因此改变胚胎已有亲本的核遗传来源；分割来源相同的早期胚胎可获得遗传背景相近的个体，但表型还受发育和环境影响。",
  "区分受精产生胚胎与移植改变发育环境|解释相同遗传背景不等于全部表型必定相同",
  q("将已形成的胚胎移入适宜受体母体继续发育，课程模型中最准确的判断是？","发育环境改变，但不因此替换胚胎已有的亲本核遗传来源|受体母体的体细胞核自动取代胚胎全部细胞核|胚胎移植等同于再发生一次精卵受精|受体母体不会对胚胎任何发育条件产生影响","移植提供新的妊娠环境，不等于重新受精或替换核基因；母体环境仍可影响发育。"),
  q("同一个早期胚胎分割形成的两个个体，即使主要遗传背景相同，为何某些性状仍可能不同？","发育过程、环境和基因表达状态等仍可影响表型|只有核DNA序列改变才可能导致表型差异|相同主要遗传背景已排除了环境对性状的影响|表型不同就足以证明二者来自不同受精卵","表型受DNA序列、表达调节、发育过程及环境等共同影响；主要遗传背景相同不能推出所有经历及性状都相同。"),
  "meiosis_two_fertilization>需理解精卵结合和亲本遗传来源;expression_traits>相近基因型仍可有环境与表达差异;~human_reproduction>胚胎发育与母体环境提供背景"),
n("somatic_nuclear_transfer",2,"体细胞核移植的遗传来源",
  "体细胞核移植利用体细胞核与去核卵母细胞形成重构细胞，并借助适宜发育条件获得胚胎等。所得个体的主要核遗传信息来自供核细胞，线粒体等细胞质来源可能不同；核基因相近不意味着全部遗传物质和表型完全相同。",
  "区分供核细胞与卵细胞质的遗传贡献|解释核移植不等于全部性状的机械复制",
  q("在体细胞核移植的典型模型中，重构胚胎的主要核遗传信息来自？","供核体细胞|去核卵母细胞提供者原来的卵细胞核|孕育胚胎的受体母体体细胞|供核个体与受体母体的细胞核各贡献一半","主要核DNA来自移入的供核体细胞核，去核卵细胞仍提供细胞质等成分；受体母体主要提供发育环境。"),
  q("为什么不能由核基因主要来自供核者，就断言核移植个体全部遗传物质和全部性状与供核者相同？","线粒体遗传来源及发育环境等可能不同|去核卵母细胞提供者仍会贡献另一套完整细胞核|受体母体核DNA会成为后代主要核遗传信息|主要核DNA相同就能排除细胞质与环境对性状的作用","供核细胞主要提供核DNA，去核卵母细胞仍提供细胞质及其中遗传物质。再加上表达重编程和发育环境等差异，不能把核来源相近等同于全部遗传物质和性状一致。"),
  "nucleus_chromatin>需理解细胞核承载主要遗传信息;organelles>线粒体与细胞质成分有独立来源;expression_traits>相同核基因不保证完全相同表型"),
n("dna_tool_enzymes",3,"限制酶与DNA连接酶的分工",
  "限制性内切核酸酶识别特定DNA序列并切开相应位置的磷酸二酯键，形成特定末端。DNA连接酶连接相邻核苷酸间的糖磷酸骨架断口；互补碱基之间的配对与骨架连接是不同作用，不能把连接酶说成形成氢键的酶。",
  "区分DNA切割与连接的化学位置|辨别碱基互补配对与磷酸二酯键连接",
  q("DNA连接酶在适宜DNA末端间主要促成哪类连接？","相邻核苷酸糖磷酸骨架间的磷酸二酯键|互补碱基间的氢键作为唯一作用|氨基酸之间的肽键|脂肪酸与甘油间的酯键","DNA连接酶连接DNA骨架的断口，不能把碱基配对的氢键与骨架的共价键混同。"),
  q("两个DNA末端的互补碱基已配对，但骨架仍有缺口。仅凭配对能否认定DNA已共价连接完整？","不能，还需相应骨架连接|能，形成氢键就自动形成全部磷酸二酯键|能，DNA的骨架本来只由氢键组成|不能，因为互补末端永远不能连接","互补配对可使末端靠近，但共价连续性还需连接骨架，二者作用不同。"),
  "dna_structure>工具酶作用必须以DNA骨架与碱基配对结构为基础;enzyme_properties>酶催化具有相应作用对象"),
n("recombinant_vector",3,"重组载体与表达元件",
  "载体可携带目标DNA并支持在适宜宿主中维持或表达，复制起点、筛选标记和表达调控元件承担不同作用。构建表达载体需考虑目标基因、启动子等与宿主的匹配，检测到一段DNA存在不保证它已正确转录或形成有功能的蛋白质。",
  "区分复制筛选与表达元件的功能|说明目标DNA存在与有效表达的证据差别",
  q("在表达载体的常见课程模型中，筛选标记主要承担哪项功能？","帮助识别或选择具有相应载体特征的细胞|作为目标基因转录开始的调控部位|作为载体复制起始的识别部位|直接决定目标蛋白在宿主中的全部折叠过程","筛选标记帮助识别候选细胞；启动子、复制起点分别与转录和复制起始有关。标记本身不保证目标蛋白的正确折叠或功能。"),
  q("载体中已插入目标编码序列，但缺少适合该宿主的相关转录调控条件，哪项推断更合理？","可能有目标DNA却没有足够的相应RNA表达|只要DNA存在就必定按相同水平表达|筛选标记的存在可完全代替启动子的作用|复制起点能自动承担所有翻译功能","DNA能维持与基因能转录表达是不同问题，需要合适的调控和宿主条件。"),
  "dna_tool_enzymes>重组DNA构建涉及切割与连接;transcription>表达元件首先影响转录;gene_definition>需明确目标基因的功能片段含义"),
n("pcr_principle",3,"PCR扩增的选择性与理论数量",
  "PCR通过模板链分开、引物配对和酶促延伸的循环扩增特定DNA区段，引物与模板的匹配参与决定区段选择。理想情况下每轮产物数可翻倍，真实反应受效率和资源限制；PCR扩增DNA不等同于直接得到相应蛋白质。",
  "说明模板引物和聚合酶在扩增中的作用|在明确理想倍增条件下计算理论产物数",
  q("从3个双链目标DNA分子出发，理想PCR每轮均使分子数翻倍，5轮后理论总数是多少？","96个|15个|48个|243个","理论数＝3×2⁵＝96；真实效率不一定始终达到理想翻倍。"),
  q("为什么PCR通常扩增选定区段，而不是把样品中的每一段DNA都同等扩增？","引物与模板的配对位置等决定可被扩增的区段|DNA聚合酶能够单独确定目标区段的两个边界|只要是DNA分子，所有区段就会以同一效率扩增|原样品中含量最多的DNA自动决定全部扩增边界","引物与模板的匹配及位置参与限定可扩增区段；聚合酶负责延伸，不能单独代替引物界定目标。模板和反应条件也会影响实际效率。"),
  "dna_replication>PCR利用模板复制与碱基配对原理;enzyme_properties>延伸依赖相应酶催化"),
n("gene_engineering_evidence",3,"基因工程流程与多层证据",
  "基因工程需将目标设计、载体构建、导入、筛选和鉴定等环节连接起来。DNA、RNA、蛋白质和生物功能处于不同证据层次，各层结果不能随意互相替代；合适的阴性和阳性对照有助于区分目标效应、背景与检测失败。",
  "区分目标DNA存在转录表达与功能证据|根据对照判断是否能把现象归于目标构建",
  q("检测到受体中含有目标DNA片段，关于目标蛋白的预期功能，哪项判断成立？","还需表达与功能层面的证据|重复检测同一DNA更多次即可代替蛋白功能检验|DNA检测阳性就已证明转录量达到预期|DNA检测阳性就已证明翻译及正确折叠均完成","DNA存在是一个证据层次；转录、翻译、蛋白折叠和具体功能均需相应证据，重复确认DNA不能代替后续层次。"),
  q("某研究比较含目标构建的细胞与只含空载体的可比细胞。空载体组主要帮助判断哪一问题？","观察到的变化是否可能由载体或处理背景造成|已知阳性样品能否被检测方法识别|目标蛋白的具体氨基酸序列是什么|目标DNA片段在基因组中的精确位置在哪里","空载体组保留载体和共同处理背景，用于控制这些因素。检测阳性对照、蛋白序列测定和插入位置分析回答其他问题。"),
  "recombinant_vector>需理解载体与目标基因各自作用;~pcr_principle>PCR是DNA检测方法之一，区分证据层次不以扩增计算为前提;translation>蛋白质形成仍需表达过程;~inquiry>功能归因依赖恰当对照"),
n("protein_engineering",3,"蛋白质工程的设计与验证",
  "蛋白质工程从期望的功能出发，研究结构与氨基酸序列的关系，并可通过改变相应基因来获得设计的蛋白质。序列改变不保证功能改善，还需评价折叠、稳定性和具体条件下的活性；设计目标与实验验证相互配合。",
  "追踪功能目标蛋白质序列与基因改造的联系|评价序列变化后为何仍需功能检测",
  q("希望改变某工业酶的氨基酸序列，常可通过哪个层面的设计使细胞合成所需变体？","按设计改变相应编码基因并检验表达产物|保持编码序列不变，仅增加基因拷贝数就能指定某位氨基酸替换|只提高原酶表达量，就必定改变每个酶分子的氨基酸序列|仅增加原酶底物浓度，就能让细胞稳定遗传指定的新编码序列","蛋白质氨基酸序列由编码信息决定，改变拷贝数、表达量或底物浓度并不能直接指定新的编码序列。"),
  q("某酶按设计替换了一个氨基酸，为什么不能仅凭替换成功就宣布性能提高？","替换可能改变折叠、稳定性或活性，需按目标条件检验|新序列与设计一致就等于催化效率必然更高|酶表达量增加足以证明每个酶分子的催化性能提高|在一个温度下活性提高即可推定所有条件下性能提高","设计序列、表达量和单一条件下的活性是不同证据；性能改进要根据实际目标条件检验结构、稳定性和功能，结果可能有利、中性或不利。"),
  "proteins>蛋白质结构与功能是设计基础;expression_traits>基因通过表达产物影响性状;gene_engineering_evidence>设计结果需多层验证"),
n("gm_safety_assessment",4,"转基因产品的证据评价",
  "评价转基因产品需针对具体性状、使用方式和暴露情境考察食品、生态等不同问题，不能仅凭转基因标签推定绝对安全或必然危险。基因改变的预期作用、意外影响、环境传播及适宜比较材料等均可构成证据，结论应有明确范围。",
  "区分产品标签与具体风险证据|将食品相关问题与生态传播问题分别评价",
  q("面对一种新转基因产品，哪种评价方式最符合证据原则？","针对具体改变、用途和暴露条件收集并比较相关证据|只要属于转基因就判定所有用途绝对安全|只要含有外源基因就判定任何用途必然危险|仅凭包装是否写转基因就能确定全部生态后果","安全评价应针对具体产品与情境，技术类别标签不能替代证据和条件。"),
  q("评估某转基因植物的基因是否可能传入附近野生近缘种，最直接相关的信息是？","是否存在可杂交近缘种及有效繁殖和基因交流条件|该食品在人体消化道中蛋白质分解的速度|目标蛋白是否可能引发人体过敏反应|食品加工后某营养成分的保留比例","本题关注环境中的基因流，应考察繁殖兼容性、接触机会及后代存续；其他信息对应不同的食品评价问题。"),
  "~gene_engineering_evidence>工程流程提供证据背景，但具体安全评价不以掌握完整流程为必要先修;speciation>基因流受繁殖与隔离条件影响;~biodiversity_protection>生态后果需考虑多样性与种间联系"),
n("cloning_ethics",4,"生殖性克隆的伦理问题",
  "讨论克隆技术需区分细胞培养、研究用途与以产生出生个体为目标的生殖性克隆。高中生物学课程标准明确将中国禁止生殖性克隆人列为学习要求，涉及受试者与后代权益、发育风险、知情同意及社会后果；某动物实验成功并不能自动解决这些伦理问题。",
  "区分细胞层面的克隆与生殖性克隆目标|说明技术可行性不能替代对权益和后果的评价|准确理解课程标准关于禁止生殖性克隆人的要求",
  q("下列哪一项最符合生殖性克隆这一目标的含义？","以克隆技术获得能够出生的完整个体|仅在培养皿中扩增一种普通细胞|仅复制一段DNA用于分析|仅生产一种单克隆抗体","生殖性克隆以产生完整出生个体为目标，与细胞扩增、DNA扩增或抗体生产层次不同。"),
  q("某动物克隆实验获得存活个体。关于把这一结果用于判断人类生殖性克隆，哪项符合课程中的伦理要求？","动物实验成功不能替代对人的权益、风险和社会后果的评价|预期经济收益较高，就可以替代对后代权益的评价|动物实验获得一次成功，就足以确定对人类的伦理正当性|当事人表示同意后，就无需再考虑后代风险与社会后果","技术上获得存活动物不等于解决人类生殖性克隆中的权益、发育风险、知情同意及社会后果等问题。所依据的中国高中生物课程标准明确禁止生殖性克隆人。"),
  "~somatic_nuclear_transfer>核移植提供机制背景，但生殖性目标与伦理不要求先会全部遗传来源细节;~embryo_engineering>不同胚胎技术目的与证据边界需区分"),
n("biosafety_responsibility",4,"生物安全与负责任的科学应用",
  "生物技术可服务健康、农业和环境，也可能因不当使用产生传播、生态或社会风险。生物安全重视风险识别、预防与规范使用，课程明确反对将生物学用于生物武器。科学价值需要与和平目的、公共利益和对后果的责任共同考虑。",
  "区分有益研究目的与可能的滥用后果|用生物传播与生态关系识别需评价的风险类型",
  q("为什么不能仅以某项生物技术能实现作为将其用于生物武器的理由？","技术可行性不能赋予危害人类的用途以正当性|只要能实现，任何用途都自动符合科学伦理|科学知识不能带来任何现实后果|只要不直接观察到后果，就不存在对他人的责任","生物学应用必须考虑目的、权益和后果，技术能力本身不是伤害性用途的正当理由。"),
  q("某项目准备将一种可繁殖生物引入新的环境。除预期用途外，哪类问题最需要纳入生态风险评价？","扩散能力、与当地物种的关系及可能的长期影响|只看短期目标产量，不考察环境中的存续|只看引入数量少，就认定以后也永远少|只看原产地有益，就认定所有新环境效果相同","生物可能繁殖、扩散并改变种间关系，风险评价需考虑长期和环境差异，不能只用初始数量或原产地经验替代。"),
  "~gm_safety_assessment>转基因评价是情境案例，生物安全一般原则不以掌握该产品类别为必要先修;interspecific_relations>扩散后果涉及种间关系;ecosystem_stability>生态风险需考虑系统响应和限度")
]
